package android.net.nsd;import java.net.*;import java.util.*;public class NsdServiceInfo{public String name,type="_flowdrop._tcp.";public int port=5173;public final Map<String,byte[]> attributes=new HashMap<>();public final List<InetAddress> addresses=new ArrayList<>();public NsdServiceInfo(String name){this.name=name;}public String getServiceName(){return name;}public String getServiceType(){return type;}public int getPort(){return port;}public Map<String,byte[]> getAttributes(){return attributes;}public List<InetAddress> getHostAddresses(){return addresses;}public InetAddress getHost(){return addresses.isEmpty()?null:addresses.get(0);}}
